
select decode("INVENTORY_ON_HAND"."BRANCH_PLANT", 'CINC', 'Americas', 'CIN2', 'Americas', 'CIN4', 'Americas', 'AUBA', 'Aubange', 'AUB2', 'Aubange', 'SING', 'Singapore', 'SNG4', 'Singapore', 'MUM3', 'India', 'SHAN', 'China', 'ERROR') "levelkey", "INVENTORY_ON_HAND"."MASTER_PLANNING_FAMILY" "Master_Planning_Familykey", "INVENTORY_ON_HAND_MEASURE"."LOT_STATUS" "Lot_Statuskey", sum(case  when "INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."CONVERSION_FACTOR_LB"<0 then -(("INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."CONVERSION_FACTOR_LB")*44) else "INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."CONVERSION_FACTOR_LB" end ) "Quantity_on_Hand_LBs", sum(("INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."UNIT_COST")*"T3"."FROM_TO_EXCHANGE_RATE") "c5"
 from "DW_LEGACY"."INVENTORY_ON_HAND" "INVENTORY_ON_HAND", "DW_LEGACY"."INVENTORY_ON_HAND_MEASURES" "INVENTORY_ON_HAND_MEASURE", "DW_LEGACY"."FIN_CURRENCY_CONVERSION" "T3"
 where "INVENTORY_ON_HAND"."INVENTORY_DATE"=CAST( ( :PQ1 ) AS TIMESTAMP ) and "INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND">0 and "INVENTORY_ON_HAND"."BRANCH_PLANT" in (N'CINC', N'CIN2', N'CIN4', N'AUBA', N'AUB2', N'SING', N'SNG4', N'MUM3', N'SHAN') and "INVENTORY_ON_HAND"."MASTER_PLANNING_FAMILY" in (N'ATP', N'ETP', N'FBW', N'FBW', N'FCB', N'FCB', N'FCB', N'FCB', N'FCB', N'FEC', N'FEC', N'FEC', N'FEC', N'FEC', N'FRC', N'FRC', N'FRC', N'FRC', N'FRC', N'RAW', N'RAW', N'RBW', N'RCB', N'RCB', N'RCB', N'REC', N'REC', N'REC', N'RRC', N'RRC', N'RRC', N'RWW', N'TOL', N'TOL', N'TOL', N'WAG') and "T3"."FROM_CURRENCY_CODE"="INVENTORY_ON_HAND_MEASURE"."CURRENCY_CODE" and "T3"."TO_CURRENCY_CODE"='USD' and "T3"."RATE_TYPE_CODE"='-' and "INVENTORY_ON_HAND"."INVENTORY_DATE">="T3"."EFFECTIVE_START_DATE" and "INVENTORY_ON_HAND"."INVENTORY_DATE"<="T3"."EFFECTIVE_END_DATE" and "INVENTORY_ON_HAND"."INVENTORY_ON_HAND_SID"="INVENTORY_ON_HAND_MEASURE"."INVENTORY_ON_HAND_SID"
 group by decode("INVENTORY_ON_HAND"."BRANCH_PLANT", 'CINC', 'Americas', 'CIN2', 'Americas', 'CIN4', 'Americas', 'AUBA', 'Aubange', 'AUB2', 'Aubange', 'SING', 'Singapore', 'SNG4', 'Singapore', 'MUM3', 'India', 'SHAN', 'China', 'ERROR'), "INVENTORY_ON_HAND"."MASTER_PLANNING_FAMILY", "INVENTORY_ON_HAND_MEASURE"."LOT_STATUS"



